// Auto-generated by r2factor. Manual edits will be overwritten on next split.

use super::misc::sorted2;
use super::types::RecoveredFacet;
use crate::mesh::types::Point;

/// Split every constraint facet using `edge` into a chain of sub-facets over
/// the (ordered, strictly interior) `splits`. With no splits this is a no-op.
pub(super) fn split_recovered_edge(
    edge: [usize; 2],
    splits: &[Point],
    points: &mut Vec<Point>,
    facets: &mut Vec<RecoveredFacet>,
) {
    if splits.is_empty() {
        return;
    }
    let first_new = points.len();
    points.extend_from_slice(splits);
    let chain_len = splits.len() + 1;

    let mut next = Vec::with_capacity(facets.len() + 2 * chain_len);
    for facet in facets.drain(..) {
        let [u, v, w] = facet.nodes;
        // Emit sub-facets chaining the split points along the directed edge
        // (from, to) as it appears in this facet's winding.
        let emit_chain = |from: usize, to: usize, apex: usize, next: &mut Vec<RecoveredFacet>| {
            let ascending = from == edge[0];
            let mut prev = from;
            for k in 0..splits.len() {
                let idx = if ascending {
                    first_new + k
                } else {
                    first_new + splits.len() - 1 - k
                };
                next.push(RecoveredFacet {
                    nodes: [prev, idx, apex],
                    marker: facet.marker,
                });
                prev = idx;
            }
            next.push(RecoveredFacet {
                nodes: [prev, to, apex],
                marker: facet.marker,
            });
        };
        if sorted2([u, v]) == edge {
            emit_chain(u, v, w, &mut next);
        } else if sorted2([v, w]) == edge {
            emit_chain(v, w, u, &mut next);
        } else if sorted2([w, u]) == edge {
            emit_chain(w, u, v, &mut next);
        } else {
            next.push(facet);
        }
    }
    *facets = next;
}

/// Split `facets[facet_idx]` into three sub-facets around `at` (the pierce
/// point of a blocking edge when available, else the centroid).
pub(super) fn split_recovered_facet(
    facet_idx: usize,
    at: Option<Point>,
    points: &mut Vec<Point>,
    facets: &mut Vec<RecoveredFacet>,
) {
    let facet = facets.swap_remove(facet_idx);
    let [a, b, c] = facet.nodes;
    let pa = points[a];
    let pb = points[b];
    let pc = points[c];
    let center = at.unwrap_or_else(|| {
        Point::new_3d(
            (pa.x + pb.x + pc.x) / 3.0,
            (pa.y + pb.y + pc.y) / 3.0,
            (pa.z + pb.z + pc.z) / 3.0,
        )
    });
    let center_idx = points.len();
    points.push(center);
    facets.push(RecoveredFacet {
        nodes: [a, b, center_idx],
        marker: facet.marker,
    });
    facets.push(RecoveredFacet {
        nodes: [b, c, center_idx],
        marker: facet.marker,
    });
    facets.push(RecoveredFacet {
        nodes: [c, a, center_idx],
        marker: facet.marker,
    });
}
